function hgEl(id){return htmlNode.getElementById(id);}
function hgFmtBytes(b,d){if(b===null||b===undefined||isNaN(b))return '--';var u=['B','KB','MB','GB','TB','PB'];var i=0;var v=Math.abs(b);while(v>=1024&&i<u.length-1){v/=1024;i++;}return (b<0?'-':'')+v.toFixed(d===undefined?1:d)+' '+u[i];}
