    tooltip.innerHTML='<div class="hg-tt-time">'+timeLabel+'</div>'+rows.map(function(r){return '<div class="hg-tt-row"><span class="hg-tt-dot" style="background:'+r.color+'"></span><span class="hg-tt-name">'+hgEsc(r.name)+'</span><span class="hg-tt-val">'+fmt(r.v)+'</span></div>';}).join('');
    tooltip.style.display='block';
    var left=ev.clientX-r.left+10;if(left+190>r.width)left=ev.clientX-r.left-200;
    tooltip.style.left=left+'px';tooltip.style.top=(ev.clientY-r.top-10)+'px';
  });
