function hgMultiSeriesFromRefId(refId,limit){
  var frames=hgSeries(refId);
  var out=frames.map(function(f,idx){
    return {name:hgSeriesName(f),t:hgFieldValues(hgTimeField(f)),v:hgFieldValues(hgNumField(f)),color:hgPalColor(idx)};
  });
  out.sort(function(a,b){
    var la=a.v.length?a.v[a.v.length-1]||0:0, lb=b.v.length?b.v[b.v.length-1]||0:0;
    return lb-la;
  });
  if(limit)out=out.slice(0,limit);
  out.forEach(function(s,idx){s.color=hgPalColor(idx);});
